contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes calldata encodedParameters, address ownedBy) public {
        require(!c.programOperators(address(this)), "caller must not be a program operator");

        address beforeRoundImplementation = c.roundImplementation();
        address beforeAlloSettings = c.alloSettings();

        bool reverted;
        try c.create(encodedParameters, ownedBy) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterRoundImplementation = c.roundImplementation();
        address afterAlloSettings = c.alloSettings();

        assert(reverted && afterRoundImplementation == beforeRoundImplementation && afterAlloSettings == beforeAlloSettings);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes calldata encodedParameters, address ownedBy) public {
        bool isOperator = c.programOperators(address(this));
        address beforeAlloSettings = c.alloSettings();
        address beforeRoundImpl = c.roundImplementation();

        bool reverted;
        address clone;
        try c.create(encodedParameters, ownedBy) returns (address created) {
            clone = created;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (isOperator && beforeAlloSettings != address(0) && beforeRoundImpl != address(0)) {
            assert(!reverted && clone == ClonesUpgradeable.predictDeterministicAddress(beforeRoundImpl, bytes32(0), address(c)));
        }
    }
}

