        c = _c;
    }

    function run(address newOwner) public {
        require(c.owner() == address(this), "test is not owner");

        if (newOwner == address(0)) {
            // transferOwnership rejects the zero address; use the zero-address rule of renounceOwnership instead
            c.renounceOwnership();
        } else {
            c.transferOwnership(newOwner);
        }

        assert((newOwner == address(0) && c.owner() == address(0)) || (newOwner != address(0) && c.owner() == newOwner));
    }
