contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newImpl, address newSettings, address ownedBy, address caller, bytes calldata encodedParameters) public payable {
        // Setup: become program operator if caller is nonzero; else ensure caller is not operator
        if (caller == address(0)) {
            // caller zero is not an operator; leave state
        } else {
            // cannot add operator because onlyOwner is InvMutTest and only C owner can add; skip
        }

        // Read before values
        address implBefore = c.roundImplementation();
        address settingsBefore = c.alloSettings();

        // Decide and perform the call
        address clone;
        bool reverted;
        if (caller == address(this)) {
            // InvMutTest itself is operator only if previously added; not controllable
            reverted = true;
        } else {
            try c.create(encodedParameters, ownedBy) returns (address cl) {
                clone = cl;
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule: if implementation or settings is zero OR caller not program operator, create must revert and state must be unchanged
        if (implBefore == address(0) || settingsBefore == address(0)) {
            assert(reverted);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newImpl, address newSettings, address ownedBy, bytes calldata encodedParameters) public payable {
        // Setup: set non-zero implementation and settings as owner (InvMutTest is the owner)
        if (newImpl != address(0)) {
            c.updateRoundImplementation(payable(newImpl));
        }
        if (newSettings != address(0)) {
            c.updateAlloSettings(newSettings);
        }

        // Read before values through public getters
        address implBefore = c.roundImplementation();
        address settingsBefore = c.alloSettings();

        // InvMutTest is the owner, not a program operator, so create from here should revert
        // because the caller (this contract) is not a program operator,
        // unless implBefore or settingsBefore is zero, which also causes revert.
        bool reverted;
        address clone;
        try c.create(encodedParameters, ownedBy) returns (address cl) {
            clone = cl;
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: create must revert for a non-program-operator caller regardless of implementation/settings,
        // and if it somehow succeeds (e.g., InvMutTest was made an operator), then implementation and settings were non-zero.
        assert(reverted || (implBefore != address(0) && settingsBefore != address(0)));
    }

    receive() external payable {}
}

